oxy_webhelp_navlinks = {"azr_workloads-d39307e22110":{"topics":[{"title":"Introduction to Azure protection","href":"saas\/azr_key_features_protection.html","menu":{"hasChildren":false},"tocID":"tocId-d39307e22124","next":"tocId-d39307e22124"},{"title":"Get started with Azure workloads protection","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects Azure workloads through a set of configuration steps         that must be completed in a specific order. Cloud account setup, Exocompute configuration,         network requirements, and SLA Domain assignment each depend on the previous step.<\/p>","href":"saas\/azr_protection_get_started.html","attributes":{"data-id":"azr_protection_get_started"},"menu":{"hasChildren":false},"tocID":"azr_protection_get_started-d39307e22233","next":"azr_protection_get_started-d39307e22233"},{"title":"Quick links for Azure workloads","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information, enabling quick setup, daily         operations, and critical recovery.<\/p>","href":"saas\/azr_quick_links.html","attributes":{"data-id":"azr_quick_links"},"menu":{"hasChildren":false},"tocID":"azr_quick_links-d39307e22274","topics":[]},{"title":"Plan your Azure protection","shortdesc":"<p class=\"shortdesc\">Before setting up an Azure cloud account in <span class=\"ph\">RSC<\/span>, you are required to         plan the user and access management for designated <span class=\"ph\">RSC<\/span> users. This planning         also involves reviewing the permissions that <span class=\"ph\">RSC<\/span> requires in your Azure         environment to protect your Azure workloads.<\/p>","href":"saas\/azr_protection_planning.html","attributes":{"data-id":"azr_protection_planning"},"menu":{"hasChildren":false},"tocID":"azr_protection_planning-d39307e22285","next":"azr_protection_planning-d39307e22285"},{"title":"Set up Azure cloud accounts","shortdesc":"<p class=\"shortdesc\">You can set up an Azure cloud account in <span class=\"ph\">RSC<\/span> to start protecting         Azure workloads.<\/p>","href":"saas\/azr_cloud_acc_setup.html","attributes":{"data-id":"azr_cloud_acc_setup"},"menu":{"hasChildren":false},"tocID":"azr_cloud_acc_setup-d39307e22602","next":"azr_cloud_acc_setup-d39307e22602"},{"title":"Set up Exocompute on Azure","shortdesc":"<p class=\"shortdesc\">With the Exocompute on Azure feature, <span class=\"ph\">RSC<\/span> launches an Azure         Kubernetes Service cluster to perform various operations to protect Azure workloads. <span class=\"ph\">RSC<\/span> uses the Azure Kubernetes Service cluster to serve as a compute resource         in your Azure subscription.<\/p>","href":"saas\/azr_exocompute.html","attributes":{"data-id":"azr_exocompute"},"menu":{"hasChildren":false},"tocID":"azr_exocompute-d39307e23354","next":"azr_exocompute-d39307e23354"},{"title":"Set up Azure storage tiering","shortdesc":"<p class=\"shortdesc\">You can use Azure storage tiering to archive Azure virtual machine or managed disk         snapshots, which are older than a specified threshold, to Azure storage access tiers. By         archiving snapshots to these access tiers, you can optimize cost.<\/p>","href":"saas\/azr_storage_tiering_setup.html","attributes":{"data-id":"azr_storage_tiering_setup"},"menu":{"hasChildren":false},"tocID":"azr_storage_tiering_setup-d39307e23985","next":"azr_storage_tiering_setup-d39307e23985"},{"title":"Set up Azure workloads protection","shortdesc":"<p class=\"shortdesc\">You can set up SLA Domains to apply data protection policies, ensuring automatic and         hierarchical protection of Azure subscriptions, resource groups, and individual Azure         workloads, with granular control overriding higher-level assignments.<\/p>","href":"saas\/azr_workloads_protection_setup.html","attributes":{"data-id":"azr_workloads_protection_setup"},"menu":{"hasChildren":false},"tocID":"azr_workloads_protection_setup-d39307e24253","next":"azr_workloads_protection_setup-d39307e24253"},{"title":"Manage Azure virtual machines","shortdesc":"<p class=\"shortdesc\">After completing the protection setup for Azure virtual machines and managed disks,             <span class=\"ph\">RSC<\/span> takes automated snapshots of those virtual machines and disks based         on the configured policies in SLA Domains. You can also take on-demand snapshots, refresh         Azure subscriptions, and add Azure custom tags for better resource management.<\/p>","href":"saas\/azr_manage_vm_md.html","attributes":{"data-id":"azr_manage_vm_md"},"menu":{"hasChildren":false},"tocID":"azr_manage_vm_md-d39307e24574","next":"azr_manage_vm_md-d39307e24574"},{"title":"Manage Azure Blob Storage","shortdesc":"<p class=\"shortdesc\">By using the protection services offered by <span class=\"ph\">RSC<\/span>, you can protect and         recover your objects in Azure Blob Storage.<\/p>","href":"azure_blob\/azr_manage_blob_storage.html","attributes":{"data-id":"azr_manage_blob_storage"},"menu":{"hasChildren":false},"tocID":"azr_manage_blob_storage-d39307e24995","next":"azr_manage_blob_storage-d39307e24995"},{"title":"Manage Azure SQL Database","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances Azure native backup capabilities for SQL Databases by         offering advanced, Rubrik-managed protection. This solution overcomes native limitations         with customizable SLA Domain policies, on-demand snapshots, and flexible cross-subscription         recovery, ensuring a consistent and automated approach to data security.<\/p>","href":"saas\/azr_sql_db_manage.html","attributes":{"data-id":"azr_sql_db_manage"},"menu":{"hasChildren":false},"tocID":"azr_sql_db_manage-d39307e25136","next":"azr_sql_db_manage-d39307e25136"},{"title":"Manage Azure SQL Managed Instance","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances Azure native backup capabilities for SQL Managed         Instances by offering advanced, Rubrik-managed protection. This solution overcomes native         limitations with customizable SLA Domain policies, on-demand snapshots, and flexible         cross-subscription recovery, ensuring a consistent and automated approach to data         security.<\/p>","href":"saas\/azr_sql_mi_manage.html","attributes":{"data-id":"azr_sql_mi_manage"},"menu":{"hasChildren":false},"tocID":"azr_sql_mi_manage-d39307e25481","next":"azr_sql_mi_manage-d39307e25481"},{"title":"Manage Azure PostgreSQL Flexible Servers","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances Azure native backup capabilities for Azure PostgreSQL         Flexible Servers by providing advanced, Rubrik-managed protection with customizable SLA         Domain policies, immutable backups, point-in-time recovery, and flexible cross-subscription         recovery.<\/p>","href":"saas\/azr_psql_manage.html","attributes":{"data-id":"azr_psql_manage"},"menu":{"hasChildren":false},"tocID":"azr_psql_manage-d39307e25840","next":"azr_psql_manage-d39307e25840"},{"title":"Recover Azure workloads","shortdesc":"<p class=\"shortdesc\">After <span class=\"ph\">RSC<\/span> takes snapshots of your Azure workloads, you can recover         the required workloads.<\/p>","href":"saas\/azr_workload_recovery.html","attributes":{"data-id":"azr_workload_recovery"},"menu":{"hasChildren":false},"tocID":"azr_workload_recovery-d39307e25888","next":"azr_workload_recovery-d39307e25888"}]}};